#!/bin/bash
# Run B Codex critique (brief "Codex in each run" step 3). Run from the project folder.
#   bash docs/renders/2026-11-09-build-fast/run-B/tools/critique.sh <out .md> <log>
codex exec --sandbox read-only --output-last-message "$1" "Critic for run B of docs/renders/2026-11-09-build-fast/TERMINAL-BRIEF.md (plan v3.2 steps 6–8: Pilot Fallback B, across journeys, final pass). Review the built app/ (mainly app/core/call-engine.js, app/screens/case.js, app/screens/skip-ha-sheet.js, app/core/call-sim.js, app/core/settings.js, app/core/boot.js) against ui-screens/app-logic.md (§4–§7, Fallback B), the approved ui-screens/case/ HTML and pictures for g0/g1/g2/g3b/t13–t17/t10b/c-skip-ha/s7d-result-missing-pilot, plan v3.2 (docs/proposals/2026-11-05-prototype-build-plan-v3.md) and tests/codex/run-B/CASES.md and REVIEW-CHECKS.md. Read docs/runs/RULINGS.md first. Report only gaps that affect correctness against the spec (behaviour, routing, gates, copy, tokens), as blockers or should-fix with file, line and spec line; skip style and preferences; also list CASES.md scenarios with no passing test (test logs: docs/renders/2026-11-09-build-fast/run-B/tests-step6/; disputes: run-B/test-disputes.md). Read-only." < /dev/null > "$2" 2>&1
echo "exit $?"; tail -3 "$1"
